62	  --ink: #1A1D21;          /* primary text, graphite */
63	  --paper: #F2F3F5;        /* page background, cool grey */
64	  --paper-raised: #FFFFFF; /* card surfaces sitting on --paper */
65	  --line: #D6D9DD;         /* hairline borders and rules */
66	  --accent: #1F5C8B;       /* primary accent, drawing blue */
67	  --accent-soft: #E4EDF4;  /* accent tint for pills and highlights */
68	
69	  /* Semantic, never repurposed as branding */
